// The OpenCode-style palette: filled panels a shade lighter than the terminal, with a coloured
// bar down their left edge in place of a border.
export const PANEL = '#30333a'
export const PROMPT_BAR = '#5b8def'
export const OUTPUT_BAR = '#4a4e57'

